import math

def solve_diophantine(n):
    # We need 24084 - 3*n^2 = K^2
    delta = 24084 - 3 * (n**2)
    if delta < 0:
        return None

    K = math.isqrt(delta)
    if K * K != delta:
        return None

    # We need r = (3n +/- K) / 6 to be an integer
    r1_numerator = 3 * n + K
    r2_numerator = 3 * n - K

    r1 = None
    if r1_numerator % 6 == 0:
        r1 = r1_numerator // 6
        if 0 <= r1 <= n:
            pass # Valid solution
        else:
            r1 = None

    r2 = None
    if r2_numerator % 6 == 0:
        r2 = r2_numerator // 6
        if 0 <= r2 <= n:
            pass # Valid solution
        else:
            r2 = None

    if r1 is not None or r2 is not None:
        return True, r1, r2
    return False, None, None

# Search range: n >= 13 (since n^3 >= 2007) and n < 69 (to find smaller solutions than W2 found)
search_limit = 69
results = []
for n in range(13, search_limit):
    success, r1, r2 = solve_diophantine(n)
    if success:
        results.append((n, r1, r2))

print("Solutions found (n, r1, r2):")
for n, r1, r2 in results:
    print(f"n={n}: r1={r1}, r2={r2}")
